دالة سطّح_القائمة(ق) {
    متغير نتائج = []
    من_أجل (ع في ق) {
        إذا (نوع(ع) == "قائمة") {
            من_أجل (ع2 في سطّح_القائمة(ع)) {
                أضف(نتائج، ع2)
            }
        } وإلا {
            أضف(نتائج، ع)
        }
    }
    ارجع نتائج
}
```

